**Gates before launch.** Before the real launch, I run this script once with `dryRun: true`. The Gates phase runs first. It stops the script if either check fails. The grader selftest builds three label files: an oracle file, an empty file, and an all-wrong file. The oracle must score 1.0 on category and on priority. The empty file and the all-wrong file must both score 0. The control step regrades the r03 trial outputs with the current grade.py. The new numbers must match the r03 numbers in spe/prediction-log.md within 0.02. After the gates, the dry run runs B and C2 once each on 5 tickets. I then check four things myself. The runner flags and output file names must match what r03 used. The peek audit must find a transcript in each run folder. The grader must return one row per ticket. The judge must return one row per reply. The script's paths and commands are args with default values. I could not check those defaults because this trial barred reading files, so the dry run is where they get confirmed. I set estTrialUsd and estJudgeUsd to the dry run's measured cost plus 25 percent. The round could need up to 16 trials (10 planned plus 6 extras). If 16 trials at that rate would cost more than $40, I tell you before launch. Then I commit the script as `SPE r04 evaluate (harness)` and launch it with `dryRun: false`. The full run repeats both gate checks.

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4 eval: configs B and C2, 50 tickets, 5 trials per cell, code grader then Opus tone judge, $40 spend cap',
  phases: [
    { title: 'Gates' },
    { title: 'Trials' },
    { title: 'Peek audit' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Extra trials' },
    { title: 'Failure analysis' },
    { title: 'Completeness critic' },
  ],
}

// The round number lives here only. Prompt text derives it from RTAG.
const ROUND = 4
const tag = (r) => `r${String(r).padStart(2, '0')}`
const RTAG = tag(ROUND)
const PREV = tag(ROUND - 1)

const A = typeof args === 'object' && args !== null ? args : {}
const DRY = A.dryRun === true
const CONFIGS = A.configs ?? [
  { id: 'B', dir: 'spe/evals/configs/B' },   // 12-line prompt, 6 tools
  { id: 'C2', dir: 'spe/evals/configs/C2' }, // 12-line prompt, 3 tools plus check_status
]
const TICKETS = A.tickets ?? 'spe/evals/tasks/tickets.json'
const ANSWERS = 'spe/evals/tasks/answers.json'
const RUBRIC = 'spe/evals/graders/judge.md'
const N = DRY ? (A.dryTickets ?? 5) : (A.nTickets ?? 50)
const TRIALS = DRY ? 1 : (A.trialsPerCell ?? 5)
const MAX_EXTRA = DRY ? 0 : (A.maxExtraPerCell ?? 3)
const SPLIT_SPREAD = A.splitSpread ?? 0.1
const CONTROL_TOL = A.controlTolerance ?? 0.02
const CAP_USD = A.capUsd ?? 40
const TRIAL_USD = A.estTrialUsd ?? (DRY ? 3 : null)
const JUDGE_USD = A.estJudgeUsd ?? (DRY ? 1 : null)
const STEP_USD = A.estStepUsd ?? 0.5
const RUN_ROOT = `spe/evals/runs/${RTAG}${DRY ? '-dry' : ''}`
const RUNNER_PATH = A.runnerPath ?? 'spe/evals/harness/run_trial.py'
const RUNNER = A.runnerCmd ?? `python ${RUNNER_PATH} --config {config} --tickets {tickets} --limit {limit} --out {out}`
const GRADE = A.gradeCmd ?? 'python spe/evals/graders/grade.py --pred {pred} --answers {answers} --json'
const MODEL = 'opus'
const FORBIDDEN = `answers\\.json|evals/graders|spe/predictions|prediction-log|failures\\.md|spe/plans|spe/spec|evals/runs/${PREV}`
const METRICS = ['category_acc', 'priority_acc', 'both_acc', 'tone_pass_rate']

const fill = (tpl, vals) => tpl.replace(/\{(\w+)\}/g, (m, k) => (k in vals ? String(vals[k]) : m))
const r3 = (x) => Math.round(x * 1000) / 1000
const avg = (xs) => xs.reduce((s, x) => s + x, 0) / xs.length

if (typeof TRIAL_USD !== 'number' || typeof JUDGE_USD !== 'number') {
  return { round: ROUND, halted: true, reason: 'A full run needs estTrialUsd and estJudgeUsd from the dry run.' }
}

// ---------- Budget: reserve before launch, skip and log when a trial would cross the cap ----------
let spent = 0
let capHit = false
const skips = []
function reserve(usd, what) {
  if (capHit || spent + usd > CAP_USD) {
    capHit = true
    skips.push({ what, est_usd: r3(usd), spent_at_skip: r3(spent) })
    log(`SKIP ${what}: est $${usd.toFixed(2)} would cross the $${CAP_USD} cap at $${spent.toFixed(2)}`)
    return false
  }
  spent += usd
  return true
}
function settle(reserved, actual) {
  if (typeof actual === 'number' && actual >= 0) spent += actual - reserved
}

// ---------- Schemas ----------
const num = { type: 'number' }
const str = { type: 'string' }
const strs = { type: 'array', items: str }
const SELFTEST_SCHEMA = {
  type: 'object',
  required: ['oracle_category', 'oracle_priority', 'empty_category', 'empty_priority', 'wrong_category', 'wrong_priority'],
  properties: {
    oracle_category: num, oracle_priority: num,
    empty_category: num, empty_priority: num,
    wrong_category: num, wrong_priority: num,
    errors: strs,
  },
}
const CONTROL_SCHEMA = {
  type: 'object',
  required: ['rows'],
  properties: {
    rows: {
      type: 'array',
      items: {
        type: 'object',
        required: ['config', 'metric', 'logged', 'regraded'],
        properties: { config: str, metric: str, logged: num, regraded: num },
      },
    },
    notes: str,
  },
}
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['status', 'runner_exit_code', 'labels_written', 'replies_written', 'files_read', 'cost_usd'],
  properties: {
    status: { enum: ['ok', 'runner_error'] },
    runner_exit_code: { type: 'integer' },
    labels_written: { type: 'integer' },
    replies_written: { type: 'integer' },
    files_read: strs,
    cost_usd: num,
    error: str,
  },
}
const AUDIT_SCHEMA = {
  type: 'object',
  required: ['transcript_found', 'hits'],
  properties: { transcript_found: { type: 'boolean' }, hits: strs },
}
const GRADE_SCHEMA = {
  type: 'object',
  required: ['n_graded', 'category_acc', 'priority_acc', 'per_ticket'],
  properties: {
    n_graded: { type: 'integer' },
    category_acc: num,
    priority_acc: num,
    per_ticket: {
      type: 'array',
      items: {
        type: 'object',
        required: ['ticket_id', 'category_ok', 'priority_ok'],
        properties: { ticket_id: str, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } },
      },
    },
    error: str,
  },
}
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['per_ticket'],
  properties: {
    per_ticket: {
      type: 'array',
      items: {
        type: 'object',
        required: ['ticket_id', 'pass', 'reason'],
        properties: { ticket_id: str, pass: { type: 'boolean' }, reason: str },
      },
    },
  },
}
const FAIL_SCHEMA = {
  type: 'object',
  required: ['failure_types'],
  properties: {
    failure_types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'is_new', 'name', 'kind', 'what', 'how_to_spot', 'seen_in', 'configs', 'fix'],
        properties: {
          id: str, is_new: { type: 'boolean' }, name: str, kind: str, what: str,
          how_to_spot: str, seen_in: strs, configs: strs, fix: str,
        },
      },
    },
    grader_suspects: strs,
    notes: str,
  },
}
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: { complete: { type: 'boolean' }, gaps: strs },
}

// ---------- Gates ----------
phase('Gates')
reserve(STEP_USD * 2, 'gates')
const gradeTpl = fill(GRADE, { answers: ANSWERS })
const gateResults = await parallel([
  () => agent(
    `You check that the round grader works before any trial runs. Work in the scratch folder ${RUN_ROOT}/selftest.
1. Build oracle.jsonl with the label for every ticket in ${ANSWERS}, copied exactly. Use the same line format the runner writes to labels.jsonl.
2. Build empty.jsonl as an empty file.
3. Build wrong.jsonl. For every ticket, set label.category to a valid category that differs from the answer. Set label.priority to a valid priority that differs from the answer.
4. Run this command once per file. Replace {pred} with the file path: ${gradeTpl}
Report the category and priority scores the grader prints for each file. Do not edit the grader. If the grader crashes on a file, report -1 for that file and quote the error in errors.`,
    { label: `${RTAG} grader selftest`, phase: 'Gates', schema: SELFTEST_SCHEMA, model: MODEL },
  ),
  () => agent(
    `You regrade last round as a control. Read spe/evals/harness/${PREV}-workflow.js to learn where its trial folders are and which config each folder belongs to.
For each ${PREV} trial folder that was not voided, run this command with {pred} set to that folder's labels file: ${gradeTpl}
Average category_acc and priority_acc per config. Then read the ${PREV} rows in spe/prediction-log.md. Copy the Measured value for the same metric and config.
Return one row per config and metric with the logged value and the regraded value. Do not edit any file.`,
    { label: `${PREV} control regrade`, phase: 'Gates', schema: CONTROL_SCHEMA, model: MODEL },
  ),
])
const selftest = gateResults[0]
const control = gateResults[1]
const selftestOk =
  selftest.oracle_category === 1 && selftest.oracle_priority === 1 &&
  selftest.empty_category <= 0 && selftest.empty_priority <= 0 &&
  selftest.wrong_category === 0 && selftest.wrong_priority === 0
const controlDiff = control.rows.length
  ? Math.max(...control.rows.map((r) => Math.abs(r.logged - r.regraded)))
  : Infinity
const controlOk = controlDiff <= CONTROL_TOL
const gates = { selftest, selftestOk, control, controlDiff: r3(controlDiff), controlOk }
log(`Gates: selftest ${selftestOk ? 'pass' : 'FAIL'}, control max diff ${r3(controlDiff)} ${controlOk ? 'pass' : 'FAIL'}`)
if (!selftestOk || !controlOk) {
  return { round: ROUND, dryRun: DRY, halted: true, reason: 'A gate failed. The grader is not trusted for this round.', gates, spend_est_usd: r3(spent) }
}

// ---------- Trial stages ----------
let counter = 0
function newJob(cfg, k, phaseName) {
  counter += 1
  // Folder names are a global counter with configs interleaved, so the judge cannot tell configs apart by path.
  return { cfg: cfg.id, cfgDir: cfg.dir, k, phaseName, runDir: `${RUN_ROOT}/trial-${String(counter).padStart(3, '0')}`, voided: null, skipped: false }
}

function trialPrompt(job, cmd) {
  return `You operate one trial of an eval harness. You do not answer tickets yourself.
Run this command from the repo root and wait for it to finish:
  ${cmd}
Rules:
- Open only these paths: ${job.cfgDir}, ${TICKETS}, ${RUNNER_PATH}, and ${job.runDir}.
- Do not open, list, search, or print anything else under spe/. Other run folders count.
- Do not edit the config, the tickets, or the runner. Do not rerun with changed flags.
- If the runner fails, set status to runner_error. Report the exit code and put the last 20 lines of stderr in error.
After it finishes, count the lines in ${job.runDir}/labels.jsonl and ${job.runDir}/replies.jsonl.
Read cost_usd from ${job.runDir}/usage.json if that file exists. If it does not exist, report -1.
List every file path you opened in files_read.`
}

async function runStage(job) {
  const est = TRIAL_USD + JUDGE_USD + 3 * STEP_USD
  if (!reserve(est, `${job.cfg} trial ${job.k}`)) return { ...job, skipped: true }
  const cmd = fill(RUNNER, { config: job.cfgDir, tickets: TICKETS, limit: N, out: job.runDir })
  const r = await agent(trialPrompt(job, cmd), { label: `${RTAG} ${job.cfg} t${job.k} run`, phase: job.phaseName, schema: TRIAL_SCHEMA, model: MODEL })
  settle(TRIAL_USD, r.cost_usd)
  const allowed = [job.cfgDir, TICKETS, RUNNER_PATH, job.runDir]
  const strays = (r.files_read || [])
    .filter((p) => p.includes('spe/'))
    .map((p) => p.replace(/^.*?(?=spe\/)/, ''))
    .filter((p) => !allowed.some((a) => p === a || p.startsWith(a + '/')))
  let voided = null
  if (r.status !== 'ok') voided = `runner_error exit ${r.runner_exit_code}`
  else if (r.labels_written !== N || r.replies_written !== N) voided = `incomplete output: ${r.labels_written} labels, ${r.replies_written} replies, expected ${N}`
  else if (strays.length) voided = `opened files outside the allowlist: ${strays.join(', ')}`
  if (voided) log(`VOID ${job.cfg} t${job.k} (${job.runDir}): ${voided}`)
  return { ...job, run: r, voided }
}

async function auditStage(job) {
  if (job.skipped || job.voided) return job
  const a = await agent(
    `You scan one trial folder for signs that the trial looked at files it must not see.
1. Confirm that ${job.runDir}/transcript.jsonl exists. Set transcript_found.
2. Run exactly: grep -rnE '${FORBIDDEN}' ${job.runDir}
Return every matching line as a hit, cut to 200 characters. Report every match. Do not decide whether a match is harmless.`,
    { label: `${RTAG} ${job.cfg} t${job.k} audit`, phase: 'Peek audit', schema: AUDIT_SCHEMA, model: MODEL },
  )
  let voided = null
  if (!a.transcript_found) voided = 'no transcript, so a peek cannot be ruled out'
  else if (a.hits.length) voided = `peeked: ${a.hits.slice(0, 3).join(' | ')}`
  if (voided) log(`VOID ${job.cfg} t${job.k} (${job.runDir}): ${voided}`)
  return { ...job, audit: a, voided }
}

async function gradeStage(job) {
  if (job.skipped || job.voided) return job
  const cmd = fill(GRADE, { pred: `${job.runDir}/labels.jsonl`, answers: ANSWERS })
  const g = await agent(
    `Run this grader command from the repo root exactly once: ${cmd}
Copy the numbers and per-ticket rows it prints. Do not compute, adjust, or round anything yourself.
If the grader errors, return n_graded 0, both accuracies 0, an empty per_ticket list, and the error text.`,
    { label: `${RTAG} ${job.cfg} t${job.k} grade`, phase: 'Grade', schema: GRADE_SCHEMA, model: MODEL },
  )
  if (g.n_graded !== N || g.per_ticket.length !== N) {
    const voided = `grader returned ${g.n_graded} graded and ${g.per_ticket.length} rows, expected ${N}`
    log(`VOID ${job.cfg} t${job.k}: ${voided}`)
    return { ...job, grade: g, voided }
  }
  const both = g.per_ticket.filter((t) => t.category_ok && t.priority_ok).length / N
  return { ...job, grade: { ...g, both_acc: r3(both) } }
}

async function judgeStage(job) {
  if (job.skipped || job.voided) return job
  const j = await agent(
    `You grade the tone of support replies. Read the rubric at ${RUBRIC} and follow it exactly.
Read the replies at ${job.runDir}/replies.jsonl. Read the ticket text for context from ${TICKETS}.
Judge each reply on its own. Do not open labels.jsonl, the answer key, any other run folder, or any plan or prediction file.
You are not told which configuration wrote these replies. Do not try to find out.
Return one row per reply with ticket_id, pass, and a one-sentence reason.`,
    { label: `${RTAG} trial judge ${job.runDir.split('/').pop()}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: MODEL },
  )
  // Recompute the rate from rows instead of trusting a summary number.
  const ids = new Set(j.per_ticket.map((t) => t.ticket_id))
  const complete = j.per_ticket.length === N && ids.size === N
  const tone = complete ? r3(j.per_ticket.filter((t) => t.pass).length / N) : null
  if (!complete) log(`JUDGE INCOMPLETE ${job.cfg} t${job.k}: ${j.per_ticket.length} rows, ${ids.size} unique, expected ${N}`)
  return { ...job, judge: j, tone, judgeComplete: complete }
}

const fullTrial = async (job) => judgeStage(await gradeStage(await auditStage(await runStage(job))))

// ---------- Cell statistics ----------
function metricsOf(t) {
  return { category_acc: t.grade.category_acc, priority_acc: t.grade.priority_acc, both_acc: t.grade.both_acc, tone_pass_rate: t.tone }
}
function cellStats(trials, cfgId) {
  const mine = trials.filter((t) => t.cfg === cfgId)
  const valid = mine.filter((t) => !t.skipped && !t.voided)
  const out = {
    config: cfgId,
    valid: valid.length,
    voided: mine.filter((t) => t.voided).length,
    skipped: mine.filter((t) => t.skipped).length,
  }
  for (const m of METRICS) {
    const xs = valid.map((t) => metricsOf(t)[m]).filter((x) => typeof x === 'number')
    out[m] = xs.length ? { mean: r3(avg(xs)), min: r3(Math.min(...xs)), max: r3(Math.max(...xs)), n: xs.length } : null
  }
  out.split = METRICS.some((m) => out[m] && out[m].max - out[m].min > SPLIT_SPREAD)
  return out
}

// ---------- Main trials ----------
phase('Trials')
const jobs = []
for (let k = 1; k <= TRIALS; k++) {
  for (const cfg of CONFIGS) jobs.push(newJob(cfg, k, 'Trials'))
}
const all = await pipeline(jobs, runStage, auditStage, gradeStage, judgeStage)

// ---------- Extra trials for split or short cells ----------
if (MAX_EXTRA > 0 && !capHit) {
  phase('Extra trials')
  const extras = await parallel(CONFIGS.map((cfg) => async () => {
    const mine = []
    for (let e = 1; e <= MAX_EXTRA && !capHit; e++) {
      const s = cellStats(all.concat(mine), cfg.id)
      if (!s.split && s.valid >= TRIALS) break
      log(`EXTRA ${cfg.id} #${e}: split=${s.split}, valid=${s.valid}`)
      mine.push(await fullTrial(newJob(cfg, TRIALS + e, 'Extra trials')))
    }
    return mine
  }))
  for (const xs of extras) all.push(...xs)
}

const cells = CONFIGS.map((cfg) => cellStats(all, cfg.id))
const trialRows = all.map((t) => ({
  config: t.cfg, k: t.k, runDir: t.runDir,
  skipped: t.skipped, voided: t.voided,
  metrics: t.grade && !t.voided ? metricsOf(t) : null,
  judge_complete: t.judgeComplete ?? null,
  runner_cost_usd: t.run ? t.run.cost_usd : null,
}))
const voids = trialRows.filter((t) => t.voided).map((t) => ({ config: t.config, k: t.k, runDir: t.runDir, reason: t.voided }))
for (const c of cells) {
  log(`${c.config}: valid ${c.valid}, both ${c.both_acc ? c.both_acc.mean : 'n/a'}, tone ${c.tone_pass_rate ? c.tone_pass_rate.mean : 'n/a'}, split ${c.split}`)
}

if (DRY) {
  const costs = trialRows.map((t) => t.runner_cost_usd).filter((x) => typeof x === 'number' && x >= 0)
  return {
    round: ROUND, dryRun: true, halted: false, gates, cells, trials: trialRows, voids, skips,
    measured_runner_cost_per_trial_usd: costs.length ? r3(avg(costs)) : null,
    spend_est_usd: r3(spent),
  }
}

// ---------- Failure analysis ----------
phase('Failure analysis')
const validTrials = all.filter((t) => !t.skipped && !t.voided)
const table = {}
for (const t of validTrials) {
  for (const row of t.grade.per_ticket) {
    table[row.ticket_id] = table[row.ticket_id] || {}
    const c = (table[row.ticket_id][t.cfg] = table[row.ticket_id][t.cfg] || { trials: 0, category_miss: 0, priority_miss: 0, tone_fail: 0 })
    c.trials += 1
    if (!row.category_ok) c.category_miss += 1
    if (!row.priority_ok) c.priority_miss += 1
  }
  for (const row of (t.judge ? t.judge.per_ticket : [])) {
    const c = table[row.ticket_id] && table[row.ticket_id][t.cfg]
    if (c && !row.pass) c.tone_fail += 1
  }
}
const misses = Object.entries(table)
  .map(([id, byCfg]) => ({ ticket_id: id, byCfg }))
  .filter((m) => Object.values(m.byCfg).some((c) => c.category_miss + c.priority_miss + c.tone_fail > 0))
let failures = null
if (reserve(STEP_USD * 4, 'failure analysis')) {
  failures = await agent(
    `You do failure analysis for SPE ${RTAG}. All trials have finished.
Valid trial folders by config:
${CONFIGS.map((c) => `- ${c.id}: ${validTrials.filter((t) => t.cfg === c.id).map((t) => t.runDir).join(', ')}`).join('\n')}
Tickets with at least one miss, with counts per config:
${JSON.stringify(misses)}
Read spe/failures.md for the existing F-numbered failure types. For the missed tickets, read the labels, replies, and transcripts in the folders above, and compare them with ${ANSWERS}.
Group the misses into failure types. Reuse an existing F-number when it fits. Mark new types with is_new true and give them the next free F-number.
For each type, give its name, kind, what happens, how to spot it, the ticket ids it was seen in, the configs it hit, and a proposed fix.
If a miss looks like a grader or answer-key error and not an agent error, list it in grader_suspects. Do not edit any file.`,
    { label: `${RTAG} failure analysis`, phase: 'Failure analysis', schema: FAIL_SCHEMA, model: MODEL },
  )
}

// ---------- Completeness critic ----------
phase('Completeness critic')
const summary = { round: ROUND, trials_per_cell: TRIALS, n_tickets: N, cap_usd: CAP_USD, spend_est_usd: r3(spent), cap_hit: capHit, gates, cells, voids, skips, trials: trialRows }
let critic = null
if (reserve(STEP_USD * 2, 'completeness critic')) {
  critic = await agent(
    `You check that SPE ${RTAG}'s eval results are complete before anyone reads them. Here is the run summary:
${JSON.stringify(summary)}
Check each of these and list every gap you find:
- Each config has at least ${TRIALS} valid trials.
- Each void has a reason, and each skip is logged with its cost estimate.
- No cell metric is null. Each judge_complete is true for valid trials.
- Each split cell got extra trials, or the summary shows why not.
- Both gates passed and their numbers are recorded.
- Estimated spend is under the cap.
- Each listed runDir exists on disk with labels.jsonl, replies.jsonl, and transcript.jsonl.
Do not edit any file. Set complete to true only if you found no gaps.`,
    { label: `${RTAG} completeness critic`, phase: 'Completeness critic', schema: CRITIC_SCHEMA, model: MODEL },
  )
}

return {
  ...summary,
  dryRun: false,
  halted: capHit,
  reason: capHit ? `Budget cap of $${CAP_USD} reached. ${skips.length} step(s) skipped.` : null,
  failures,
  critic,
}
```
